insert into products (name, category, tagline, description, image_url, accent_color, bg_color, serving_size, highlights, ingredients, nutrition, sort_order, old_import_id) values ('Πορτοκάλι', 'juice', '20% φυσικός χυμός + βιταμίνη C', 'Φτιαγμένο από τα πιο νόστιμα πορτοκάλια, με 20% φυσικό χυμό και έξτρα βιταμίνη C. Το Keanita Πορτοκάλι είναι φτιαγμένο ειδικά για παιδιά — θρεπτικό, τονωτικό και γεμάτο τις γεύσεις που αγαπούν.', 'products/juice-orange-new.png', '#F5A623', '#FFF6E8', 'ανά 100ml', array['20% Φυσικός χυμός','Έξτρα βιταμίνη C','Χωρίς συντηρητικά']::text[], array['Νερό','20% Χυμός πορτοκαλιού από συμπυκνωμένο','Ζάχαρη','Φυσικό άρωμα πορτοκαλιού','Βιταμίνη C (ασκορβικό οξύ)']::text[], '[{"label":"Ενέργεια","value":"184kJ / 43kcal"},{"label":"Λιπαρά","value":"0g"},{"label":"— εκ των οποίων κορεσμένα","value":"0g"},{"label":"Υδατάνθρακες","value":"10.8g"},{"label":"Σάκχαρα","value":"10.8g"},{"label":"Πρωτεΐνη","value":"0g"},{"label":"Αλάτι","value":"0g"},{"label":"Βιταμίνη C","value":"12mg"}]', 0, 1);
insert into products (name, category, tagline, description, image_url, accent_color, bg_color, serving_size, highlights, ingredients, nutrition, sort_order, old_import_id) values ('Μάνγκο', 'juice', 'Τροπική απόλαυση μάνγκο', 'Το μάνγκο — ο «βασιλιάς των φρούτων» — μέσα σε ένα παιδικό κουτάκι. Πλούσιο σε φυτικές ίνες, χωρίς συντηρητικά και με έξτρα βιταμίνη C, το Keanita Μάνγκο είναι ο τέλειος ξεδιψαστής.', 'products/juice-mango.png', '#6BBF6A', '#EEFBEE', 'ανά 100ml', array['20% Φυσικός χυμός','Πλούσιο σε φυτικές ίνες','Έξτρα βιταμίνη C']::text[], array['Νερό','20% Πουρές μάνγκο από συμπυκνωμένο','Ζάχαρη','Φυσικό άρωμα μάνγκο','Βιταμίνη C (ασκορβικό οξύ)']::text[], '[{"label":"Ενέργεια","value":"221kJ / 52kcal"},{"label":"Λιπαρά","value":"0g"},{"label":"— εκ των οποίων κορεσμένα","value":"0g"},{"label":"Υδατάνθρακες","value":"12.8g"},{"label":"Σάκχαρα","value":"12.8g"},{"label":"Πρωτεΐνη","value":"0g"},{"label":"Αλάτι","value":"0g"},{"label":"Βιταμίνη C","value":"12mg"}]', 1, 2);
insert into products (name, category, tagline, description, image_url, accent_color, bg_color, serving_size, highlights, ingredients, nutrition, sort_order, old_import_id) values ('Frumix', 'juice', 'Ένα μείγμα 5 φρούτων', 'Μια φρουτοσαλάτα μέσα σε ένα μικρό κουτάκι! Με έξτρα βιταμίνη C, χωρίς συντηρητικά, περισσότερο φυσικό χυμό και τη γεύση 5 φρούτων — μήλο, πορτοκάλι, ανανάς, ροδάκινο και μάνγκο.', 'products/juice-frumix.png', '#5DADE2', '#EDF7FD', 'ανά 100ml', array['Μείγμα 5 φρούτων','Έξτρα βιταμίνη C','Χωρίς συντηρητικά']::text[], array['Νερό','Χυμός μήλου από συμπυκνωμένο','Χυμός πορτοκαλιού από συμπυκνωμένο','Χυμός ανανά από συμπυκνωμένο','Πουρές ροδάκινου','Πουρές μάνγκο','Ζάχαρη','Βιταμίνη C (ασκορβικό οξύ)']::text[], '[{"label":"Ενέργεια","value":"191kJ / 45kcal"},{"label":"Λιπαρά","value":"0g"},{"label":"— εκ των οποίων κορεσμένα","value":"0g"},{"label":"Υδατάνθρακες","value":"11.3g"},{"label":"Σάκχαρα","value":"11.3g"},{"label":"Πρωτεΐνη","value":"0g"},{"label":"Αλάτι","value":"0g"},{"label":"Βιταμίνη C","value":"12mg"}]', 2, 3);
insert into products (name, category, tagline, description, image_url, accent_color, bg_color, serving_size, highlights, ingredients, nutrition, sort_order, old_import_id) values ('Πορτοκάλι Στέβια', 'juice', 'Λιγότερη ζάχαρη, ίδια γεύση', 'Η αυθεντική γεύση Keanita Πορτοκάλι με 20% φυσικό χυμό και έξτρα βιταμίνη C — γλυκαμένη φυσικά με εκχύλισμα φύλλων στέβιας, χωρίς προσθήκη ζάχαρης.', 'products/juice-stevia.png', '#6BBF6A', '#EEFBEE', 'ανά 100ml', array['Χωρίς προσθήκη ζάχαρης','Γλυκαμένο με στέβια','Έξτρα βιταμίνη C']::text[], array['Νερό','20% Χυμός πορτοκαλιού από συμπυκνωμένο','Φυσικό άρωμα πορτοκαλιού','Γλυκοζίτες στεβιόλης (από φύλλα στέβιας)','Βιταμίνη C (ασκορβικό οξύ)']::text[], '[{"label":"Ενέργεια","value":"100kJ / 24kcal"},{"label":"Λιπαρά","value":"0g"},{"label":"— εκ των οποίων κορεσμένα","value":"0g"},{"label":"Υδατάνθρακες","value":"6.0g"},{"label":"Σάκχαρα","value":"5.8g"},{"label":"Πρωτεΐνη","value":"0g"},{"label":"Αλάτι","value":"0g"},{"label":"Βιταμίνη C","value":"12mg"}]', 3, 4);
insert into products (name, category, tagline, description, image_url, accent_color, bg_color, serving_size, highlights, ingredients, nutrition, sort_order, old_import_id) values ('Γιαούρτι Φράουλα', 'yogurt', 'Βελούδινο με αληθινή φράουλα', 'Νόστιμο, φραουλένιο και εμπλουτισμένο με ασβέστιο και βιταμίνη D. Το τέλειο σνακ για παιδιά — για πρωινό, απογευματινή τόνωση, ή ακόμη και για πάρτι γενεθλίων!', 'products/yogurt-strawberry.png', '#E84D3D', '#FFF0EE', 'ανά 100g', array['Πλούσιο σε ασβέστιο','Πηγή βιταμίνης D','Αληθινή φράουλα']::text[], array['Παστεριωμένο αγελαδινό γάλα','Κομμάτια φράουλας (8%)','Ζάχαρη','Αποβουτυρωμένο γάλα σε σκόνη','Τρούφα σοκολάτας','Καλλιέργειες γιαουρτιού','Βιταμίνη D']::text[], '[{"label":"Ενέργεια","value":"471kJ / 112kcal"},{"label":"Λιπαρά","value":"3.4g"},{"label":"— εκ των οποίων κορεσμένα","value":"2.1g"},{"label":"Υδατάνθρακες","value":"16g"},{"label":"— εκ των οποίων σάκχαρα","value":"12g"},{"label":"Πρωτεΐνη","value":"4.3g"},{"label":"Αλάτι","value":"0.12g"},{"label":"Ασβέστιο","value":"140mg (26% NRV*)"},{"label":"Βιταμίνη D","value":"0.7µg (20% NRV*)"}]', 4, 5);
insert into characters (id, slug, name, tagline, description, best_friend, power, favorite_juice, image_url, accent_color, bg_color, sort_order) values (1, 'keanita', 'KEANITA', 'Η εξερευνήτρια του χυμού', 'Η KEANITA είναι ένα ξέγνοιαστο κορίτσι που αγαπά τη φύση, συναισθηματική και συμπονετική. Είναι δραστήρια και της αρέσουν η γυμναστική και η κηπουρική γιατί λατρεύει τη φύση! Ταξιδεύει στον κόσμο των υπολογιστών με χαρά και περιέργεια σαν εξερευνήτρια. Στο σπίτι την υποδέχονται η οικογένειά της και ο απίστευτα αξιολάτρευτος σκύλος ΤΟΝΙ!', 'Ο Βίκτωρας (αλληλοσυμπληρώνονται)', null, 'Πορτοκάλι', 'characters/character-1.png', '#1E9A3D', '#DCF5DC', 0) on conflict (slug) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description;
insert into characters (id, slug, name, tagline, description, best_friend, power, favorite_juice, image_url, accent_color, bg_color, sort_order) values (2, 'viktoras', 'ΒΙΚΤΩΡΑΣ', 'Ο ιδιοφυής εξερευνητής', 'Ο Βίκτωρας είναι ένα ήσυχο αγόρι που περνά τον χρόνο του διαβάζοντας. Είναι εξαιρετικά έξυπνος — το IQ του ξεπερνά το 300. Γνωρίζει κάθε λεπτομέρεια από τις τελευταίες παγκόσμιες ειδήσεις, και οτιδήποτε έχει να κάνει με το πώς μπορεί κανείς να επιβιώσει κάτω από οποιεσδήποτε συνθήκες. Αν και ντροπαλός, είναι υπεύθυνος στον ρόλο του και πολύ πρακτικός. Εξοπλισμένος με έντονη ερευνητική διαίσθηση και gadget υψηλής τεχνολογίας που τον βοηθούν στις αποστολές του.', 'Η KEANITA (τη θαυμάζει και είναι κρυφά ερωτευμένος)', null, 'Μήλο', 'characters/character-2.png', '#E11915', '#FFD9D4', 1) on conflict (slug) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description;
insert into characters (id, slug, name, tagline, description, best_friend, power, favorite_juice, image_url, accent_color, bg_color, sort_order) values (3, 'magkas', 'ΜΑΓΚΑΣ', 'Ο κύριος του καιρού', 'Ο Μάγκας είναι ένας απόμακρος και σκληρός χαρακτήρας, με προστατευτική όμως διάθεση. Δεν του αρέσει όταν κάποιος αμφισβητεί τις ηγετικές του ικανότητες, και λατρεύει όταν οι συμβουλές και οι απόψεις του ακούγονται χωρίς δισταγμό. Έχει την ικανότητα να μετρά τα πάντα με το καλαμάκι-κεφάλι του.', 'Ο Λέφης (τον νιώθει σαν φύλακα άγγελό του)', 'Μπορεί να αλλάζει τις καιρικές συνθήκες και να δημιουργεί τυφώνες, σεισμούς, λιακάδα, καταιγίδες κ.λπ. όποτε το επιλέξει', 'Frumix', 'characters/character-3.png', '#1E9A3D', '#DCF5DC', 2) on conflict (slug) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description;
insert into characters (id, slug, name, tagline, description, best_friend, power, favorite_juice, image_url, accent_color, bg_color, sort_order) values (4, 'lefis', 'ΛΕΦΗΣ', 'Ο μεταμορφωτής', 'Ο Λέφης είναι γεμάτος γοητεία και χαμόγελα και πιστεύει ότι ακόμη και οι κακοί έχουν κάποια ευαισθησία, γι'' αυτό προσπαθεί να οδηγήσει τους πάντες στον σωστό δρόμο χωρίς να χρησιμοποιεί τις δυνάμεις του. Του αρέσουν τα όμορφα και στιλάτα κορίτσια και οτιδήποτε χνουδωτό και απαλό. Δεν μπορεί να προφέρει το γράμμα Σ (μιλά με Θ — π.χ. «θέλειθ να χορέψουμε;»).', 'Ο Μάγκας (φαίνεται να ξέρει πολλά και του έχει σώσει τη ζωή πολλές φορές)', 'Μπορεί να πάρει όποια μορφή θέλει', 'Μάνγκο', 'characters/character-4.png', '#E11915', '#FFD9D4', 3) on conflict (slug) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description;
insert into events (type, title, description, date, time_label, location, image_url, accent_color, bg_color, status, sort_order, old_import_id) values ('event', 'Ημέρα διασκέδασης στο Riverland', 'Εργαστήρι κηπουρικής, μάθημα μαγειρικής & δραστηριότητες φάρμας για παιδιά 5-11!', '2026-04-15', '11:00 - 13:00', 'Riverland Bio Farm', 'events/event-riverland.jpg', '#E84D3D', '#FFF0EE', 'published', 0, 1);
insert into events (type, title, description, date, time_label, location, image_url, accent_color, bg_color, status, sort_order, old_import_id) values ('event', 'Πάρτι γενεθλίων Keanita', 'Έλα στη μεγάλη γιορτή γενεθλίων της Keanita με παιχνίδια και δώρα!', '2026-05-01', '15:00 - 20:00', 'Εργοστάσιο KEAN, Λεμεσός', 'events/event-birthday.jpg', '#F5A623', '#FFF6E8', 'published', 1, 3);
